#!/usr/bin/env python3
"""words.json -> sentences.json Pipeline fuer Jumlah (Task A2).

Urspruenglich als "Python + OpenAI GPT-4"-Pipeline geplant. Auf
Nutzerwunsch stattdessen von Claude direkt verfasst (siehe changelog.md) -
kein API-Call, keine Rate-Limiting/Checkpoint-Logik noetig. Der Inhalt
(SENTENCES unten) ist die eigentliche "Generierung"; dieses Script
validiert ihn gegen assets/data/words.json und exportiert
assets/data/sentences.json im dokumentierten Format.

3 Saetze pro Wort (bewusst reduziert von den urspruenglich geplanten 10,
um Qualitaet/Konsistenz bei manueller Erstellung sicherzustellen).
"""

import argparse
import json
import re
import sys
import unicodedata
from pathlib import Path

ARABIC_CHAR_RE = re.compile(r"^[؀-ۿ\s.:،؟!]+$")
HARAKAT_RE = re.compile(r"[ً-ْٰ]")
FORBIDDEN_ALLAH_TRANSLATION_RE = re.compile(r"\bgott(es)?\b", re.IGNORECASE)


def _mentions_allah(arabic_text: str) -> bool:
    """True, wenn [arabic_text] (Satz oder einzelnes Wort) 'الله' enthaelt,
    unabhaengig von Harakat. Nutzer-Vorgabe: 'Allah' wird nie uebersetzt
    (nicht als 'Gott'/'Gottes') - siehe Validierung in main()."""
    return "الله" in HARAKAT_RE.sub("", arabic_text)

